create or replace function public.product_charge_rule_put_v610(p_tenant_id uuid,p_location_id uuid,p_device_id uuid,p_rule_id uuid,p_product_variant_id uuid,p_charge_catalog_id uuid,p_order_type text,p_quantity_mode text,p_quantity_value numeric,p_active boolean) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_id uuid; begin perform private.erp_validate_vertical_device_scope(p_tenant_id,p_location_id,p_device_id,'restaurant','operate'); if not(private.erp_user_is_owner(p_tenant_id) or private.erp_has_permission(p_tenant_id,'restaurant.manage') or private.erp_has_permission(p_tenant_id,'sales.manage')) then raise exception 'Manage permission required'; end if; if not exists(select 1 from public.product_variants where id=p_product_variant_id and tenant_id=p_tenant_id and status='active') then raise exception 'Product variant not found'; end if; if not exists(select 1 from public.sales_charge_catalog_v610 where id=p_charge_catalog_id and tenant_id=p_tenant_id and active) then raise exception 'Commercial charge not found'; end if; if p_rule_id is null then insert into public.product_charge_rules_v610(tenant_id,product_variant_id,charge_catalog_id,order_type,quantity_mode,quantity_value,active) values(p_tenant_id,p_product_variant_id,p_charge_catalog_id,lower(trim(p_order_type)),lower(trim(p_quantity_mode)),p_quantity_value,coalesce(p_active,true)) returning id into v_id; else update public.product_charge_rules_v610 set product_variant_id=p_product_variant_id,charge_catalog_id=p_charge_catalog_id,order_type=lower(trim(p_order_type)),quantity_mode=lower(trim(p_quantity_mode)),quantity_value=p_quantity_value,active=coalesce(p_active,true),updated_at=now() where id=p_rule_id and tenant_id=p_tenant_id returning id into v_id; end if; if v_id is null then raise exception 'Product charge rule not found'; end if; return v_id; end; $$;;
